    openModal('會議紀錄對照 · ' + e.title, `<div class="eyebrow">對照本案的功能、DEMPE、風險與資產</div><h2>${esc(e.title)}</h2><p><b>本案要確認。</b>${esc(e.question)}</p><p><b>核心。</b>${esc(e.concept)}</p><h3>和本案同一批島嶼的紀錄</h3><div class="minute-list">${rows.map(button).join('') || '<p>還沒有。先到相關島嶼訪談，問完按「整理成會議紀錄」。</p>'}</div><button class="primary" id="minute-back">回到目前現場</button>`);
